import type { CSSProperties, ReactNode } from 'react'
import './index.less'

interface PageBackgroundProps {
  children: ReactNode
  decoration?: string
  decorationHeight?: number
  decorationPosition?: 'top' | 'bottom'
  className?: string
}

const PageBackground = ({
  children,
  decoration,
  decorationHeight,
  decorationPosition = 'top',
  className,
}: PageBackgroundProps) => {
  const rootClassName = ['page-background', className].filter(Boolean).join(' ')
  const style: CSSProperties = decorationHeight
    ? ({
        ['--page-background-decoration-height' as const]:
          `${decorationHeight}px`,
      } as CSSProperties)
    : {}

  return (
    <div className={rootClassName} style={style}>
      <div className="page-background__content">{children}</div>
      {decoration && (
        <div
          className={`page-background__decoration page-background__decoration--${decorationPosition}`}
          style={{ backgroundImage: `url(${decoration})` }}
          aria-hidden
        />
      )}
    </div>
  )
}

export default PageBackground
