import type { ReactNode, ElementType } from 'react'
import './index.less'

interface CHeadingProps {
  children: ReactNode
  level: 'display' | 'lg' | 'md'
  as?: 'h1' | 'h2' | 'h3'
  align?: 'left' | 'center'
  className?: string
}

const CHeading = ({
  children,
  level,
  as,
  align,
  className = '',
}: CHeadingProps) => {
  const defaultTag: Record<string, ElementType> = {
    display: 'h1',
    lg: 'h1',
    md: 'h2',
  }
  const Tag = (as || defaultTag[level]) as ElementType

  const classNames = [
    'c-heading',
    `c-heading--${level}`,
    align ? `c-heading--${align}` : '',
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return <Tag className={classNames}>{children}</Tag>
}

export default CHeading
