import type { ReactNode } from 'react'
import './index.less'

interface CSectionProps {
  children: ReactNode
  tone?: 'default' | 'gray' | 'rounded'
  spacing?: 'normal' | 'loose' | 'loose-sm'
  className?: string
}

const CSection = ({
  children,
  tone = 'default',
  spacing = 'normal',
  className = '',
}: CSectionProps) => {
  const classNames = [
    'c-section',
    `c-section--${tone}`,
    `c-section--${spacing}`,
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return <section className={classNames}>{children}</section>
}

export default CSection
