import type { ReactNode } from 'react'
import './index.less'

interface CStackProps {
  children: ReactNode
  direction?: 'vertical' | 'horizontal'
  gap?: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | 'xxl' | '3xl' | '4xl'
  align?: 'start' | 'center' | 'stretch'
  wrap?: boolean
  className?: string
}

const CStack = ({
  children,
  direction = 'vertical',
  gap = 'md',
  align,
  wrap,
  className = '',
}: CStackProps) => {
  const classNames = [
    'c-stack',
    `c-stack--${direction}`,
    `c-stack--gap-${gap}`,
    align ? `c-stack--align-${align}` : '',
    wrap ? 'c-stack--wrap' : '',
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return <div className={classNames}>{children}</div>
}

export default CStack
